const ps = $input.all().map((i) => i.json).filter((p) => p.tipo);
if (!ps.length) return [];
// "Roseli de Souza" vira "Roseli Souza" (antes saía "Roseli de")
const nome = (p) => (p.nome || 'cliente').split(' ').filter((w) => w && !/^(de|da|do|das|dos|e)$/i.test(w)).slice(0, 2).join(' ');
// "hoje às 18:27", "ontem às 18:27" ou "20/10 às 18:27": sem o dia, um horário de ontem confunde
const diaDe = (d) => d.toLocaleDateString('en-CA', { timeZone: 'America/Cuiaba' });
const hora = (p) => {
  if (!p.inicio) return '';
  const d = new Date(p.inicio);
  const h = d.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Cuiaba' });
  const hoje = diaDe(new Date()), ontem = diaDe(new Date(Date.now() - 86400000)), dia = diaDe(d);
  return (dia === hoje ? 'hoje' : dia === ontem ? 'ontem' : dia.slice(8) + '/' + dia.slice(5, 7)) + ' às ' + h;
};
const brl = (v) => Number(v).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', maximumFractionDigits: 0 });
const linha = (p) => {
  if (p.tipo === 'avaliacao_sem_resultado') return '• Como foi a avaliação de *' + nome(p) + '* (' + hora(p) + ')? Fechou?';
  if (p.tipo === 'atraso_confirmar') return '• *' + nome(p) + '* (' + hora(p) + ') não chegou nem respondeu. Ela está aí? *veio* ou *libera*';
  if (p.tipo === 'atendimento_sem_status') return '• *' + nome(p) + '* (' + hora(p) + (p.servico ? ', ' + p.servico.toLowerCase() : '') + ') veio?';
  // supabase/038: fechou e a aplicação ainda não está na agenda
  if (p.tipo === 'fechou_sem_data') return p.proximo_passo
    ? '• *' + nome(p) + '* fechou — ' + p.proximo_passo + '. O cabelo já chegou? Já dá pra marcar a aplicação?'
    : '• *' + nome(p) + '* fechou. O que ficou combinado e quando ela volta? Se depende do cabelo: chega em quantos dias e precisa confeccionar?';
  return '• *' + nome(p) + '* ficou de pensar' + (p.valor_orcado ? ' (' + brl(p.valor_orcado) + ')' : '') + '. Alguma novidade?';
};
const texto = ('Oi, ' + $('Loja').first().json.dona + '! Me conta pra eu anotar aqui:\n') + ps.map(linha).join('\n') + '\n\nPode responder em áudio, do seu jeito 🙂';
const quandoFoi = (ms) => { const d = new Date(ms - 4 * 3600e3); const p = (n) => String(n).padStart(2, '0'); return ['dom', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb'][d.getUTCDay()] + ' ' + p(d.getUTCDate()) + '/' + p(d.getUTCMonth() + 1) + ' ' + p(d.getUTCHours()) + ':' + p(d.getUTCMinutes()); };
const ids = ps.map((p) => p.pendencia_id);
const numeros = (('' + $('Loja').first().json.assist + '') || ('' + $('Loja').first().json.assist + '')).split(',').map(s => s.trim()).filter(Boolean);
return numeros.map((tel) => ({ json: { tel, texto, ids,
  // mesma estrutura que o nó de memória do n8n grava, para o agente saber o que perguntou
  memoria: JSON.stringify({ type: 'ai', data: { content: '[' + quandoFoi(Date.now()) + '] ' + texto, additional_kwargs: {}, response_metadata: {}, tool_calls: [], invalid_tool_calls: [] } }) } }));

// Ficha da loja deste atendimento (motor único). Tudo o que muda de uma loja para outra sai daqui.
const bruto = $('Entrada do motor').first().json.loja_json;
const f = typeof bruto === 'string' ? JSON.parse(bruto || 'null') : bruto;
if (!f || !f.empresa_id) return [];
const sem9 = (n) => { const d = String(n).replace(/\D/g, ''); return /^55\d{2}9\d{8}$/.test(d) ? d.slice(0, 4) + d.slice(5) : d; };
const lista = (v) => (Array.isArray(v) ? v : String(v || '').split(',')).map((s) => String(s).trim()).filter(Boolean);
const dona = String(f.dona || 'responsável').trim();
// Trava de teste: números com e sem o 9 (o principal compara como o WhatsApp manda; as rotinas, sem o 9).
// Loja ainda não liberada pela agência (config.ia.liberada) e sem lista: ninguém recebe, só a dona.
let permitidos = [...new Set(lista(f.permitidos).flatMap((n) => [n.replace(/\D/g, ''), sem9(n)]).filter(Boolean))];
if (f.liberada !== true && !permitidos.length) permitidos = ['0'];
if (f.liberada === true) permitidos = [];
return [{ json: {
  empresa_id: f.empresa_id, nome: f.nome || '', nicho: f.nicho || '', instancia: f.instancia || '',
  dona, dona_maiuscula: dona.toUpperCase(), nome_maiusculo: String(f.nome || '').toUpperCase(), cidade: f.cidade || '', fuso: f.fuso || 'America/Cuiaba',
  assist: lista(f.assist).join(','), assist_sem9: lista(f.assist).map(sem9).join(','),
  permitidos: permitidos.join(','), catalogo_link: f.catalogo_link || '',
  // tempo mínimo que cada cliente ocupa na agenda (config.ia.bloco_min); 0 = vale o tempo de cada serviço
  bloco_min: Number.isInteger(Number(f.bloco_min)) && Number(f.bloco_min) >= 30 && Number(f.bloco_min) <= 480 ? Number(f.bloco_min) : 0,
  // a ficha passa de um workflow para outro (loja_json) e é lida de novo por este mesmo código: liberada vai junto
  liberada: f.liberada === true,
  // teto de conversas do mês (supabase/048): no_limite = a loja chegou ao teto; conversa_barrada = além disso,
  // quem mandou esta mensagem ainda não falou com a IA hoje (conversa nova)
  limite_mes: f.limite_mes ?? null, uso_mes: f.uso_mes ?? null, no_limite: f.no_limite === true, conversa_barrada: f.conversa_barrada === true,
} }];
